import { describe, it, expect, vi, beforeEach } from 'vitest'
import { renderHook, waitFor } from '@testing-library/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import React from 'react'
import { useDayChairColumns } from '../use-day-chair-columns'

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeWrapper() {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: 0 } },
  })
  return ({ children }: { children: React.ReactNode }) =>
    React.createElement(QueryClientProvider, { client }, children)
}

const TODAY = new Date('2026-04-23T00:00:00.000Z')

const ARTISTS = [
  { id: 'artist-1', display_name: 'Alice', avatar_url: null, sort_order: 1, status: 'active' },
  { id: 'artist-2', display_name: 'Bob',   avatar_url: '/bob.jpg', sort_order: 2, status: 'active' },
  { id: 'artist-3', display_name: 'Carol', avatar_url: null, sort_order: 3, status: 'active' },
]

const BLOCKED_SLOTS = {
  data: [
    {
      artist_id: 'artist-1',
      blocked: [
        { id: 'bs-1', start_at: '2026-04-23T09:00:00Z', end_at: '2026-04-23T10:00:00Z' },
      ],
    },
    {
      artist_id: 'artist-2',
      blocked: [],
    },
  ],
}

const BOOKING_ARTIST_1 = {
  id: 'booking-1',
  studio_id: 'studio-1',
  artist: { id: 'artist-1', display_name: 'Alice', color_index: 1 },
  client: { id: 'client-1', name: 'John', email: 'j@x.com', phone: null },
  service: { id: 'svc-1', name: 'Sleeve', color: '#000' },
  scheduled_at: '2026-04-23T11:00:00Z',
  end_at: '2026-04-23T13:00:00Z',
  duration_min: 120,
  status: 'confirmed' as const,
  notes: null,
  client_id: 'client-1',
  artist_id: 'artist-1',
  service_id: 'svc-1',
  created_at: '2026-04-23T00:00:00Z',
  updated_at: '2026-04-23T00:00:00Z',
  deposit_cents: 0,
  deposit_paid: false,
  booking_participants: [],
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('useDayChairColumns', () => {
  beforeEach(() => {
    vi.restoreAllMocks()
  })

  it('returns empty array when artistsData is not yet loaded', async () => {
    // Fetch never resolves → isLoadingArtists = true, columns = []
    vi.spyOn(globalThis, 'fetch').mockImplementation(() => new Promise(() => {/* never */}))

    const { result } = renderHook(
      () => useDayChairColumns({ date: TODAY, bookings: [], filterArtistIds: [] }),
      { wrapper: makeWrapper() }
    )

    expect(result.current.columns).toEqual([])
    expect(result.current.isLoadingArtists).toBe(true)
  })

  it('builds one ChairColumn per active artist when no bookings exist', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation((url) => {
      const u = String(url)
      if (u.includes('/api/artists')) {
        return Promise.resolve(new Response(JSON.stringify({ data: ARTISTS }), { status: 200 }))
      }
      return Promise.resolve(new Response(JSON.stringify({ data: [] }), { status: 200 }))
    })

    const { result } = renderHook(
      () => useDayChairColumns({ date: TODAY, bookings: [], filterArtistIds: [] }),
      { wrapper: makeWrapper() }
    )

    await waitFor(() => expect(result.current.isLoadingArtists).toBe(false))

    expect(result.current.columns).toHaveLength(3)
    expect(result.current.columns.map((c) => c.artistId)).toEqual([
      'artist-1', 'artist-2', 'artist-3',
    ])
    // All columns have empty bookings
    result.current.columns.forEach((col) => {
      expect(col.bookings).toEqual([])
    })
  })

  it('sorts columns by sort_order ascending', async () => {
    const shuffled = [...ARTISTS].reverse() // Carol, Bob, Alice
    vi.spyOn(globalThis, 'fetch').mockImplementation((url) => {
      const u = String(url)
      if (u.includes('/api/artists')) {
        return Promise.resolve(new Response(JSON.stringify({ data: shuffled }), { status: 200 }))
      }
      return Promise.resolve(new Response(JSON.stringify({ data: [] }), { status: 200 }))
    })

    const { result } = renderHook(
      () => useDayChairColumns({ date: TODAY, bookings: [], filterArtistIds: [] }),
      { wrapper: makeWrapper() }
    )

    await waitFor(() => expect(result.current.isLoadingArtists).toBe(false))

    const names = result.current.columns.map((c) => c.displayName)
    expect(names).toEqual(['Alice', 'Bob', 'Carol'])
  })

  it('applies filterArtistIds — only matching artists appear', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation((url) => {
      const u = String(url)
      if (u.includes('/api/artists')) {
        return Promise.resolve(new Response(JSON.stringify({ data: ARTISTS }), { status: 200 }))
      }
      return Promise.resolve(new Response(JSON.stringify({ data: [] }), { status: 200 }))
    })

    const { result } = renderHook(
      () =>
        useDayChairColumns({
          date: TODAY,
          bookings: [],
          filterArtistIds: ['artist-2'],
        }),
      { wrapper: makeWrapper() }
    )

    await waitFor(() => expect(result.current.isLoadingArtists).toBe(false))

    expect(result.current.columns).toHaveLength(1)
    expect(result.current.columns[0].artistId).toBe('artist-2')
  })

  it('filterArtistIds = [] shows all artists (no filter applied)', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation((url) => {
      const u = String(url)
      if (u.includes('/api/artists')) {
        return Promise.resolve(new Response(JSON.stringify({ data: ARTISTS }), { status: 200 }))
      }
      return Promise.resolve(new Response(JSON.stringify({ data: [] }), { status: 200 }))
    })

    const { result } = renderHook(
      () =>
        useDayChairColumns({ date: TODAY, bookings: [], filterArtistIds: [] }),
      { wrapper: makeWrapper() }
    )

    await waitFor(() => expect(result.current.isLoadingArtists).toBe(false))
    expect(result.current.columns).toHaveLength(3)
  })

  it('merges bookings into the correct artist column', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation((url) => {
      const u = String(url)
      if (u.includes('/api/artists')) {
        return Promise.resolve(new Response(JSON.stringify({ data: ARTISTS }), { status: 200 }))
      }
      return Promise.resolve(new Response(JSON.stringify({ data: [] }), { status: 200 }))
    })

    const { result } = renderHook(
      () =>
        useDayChairColumns({
          date: TODAY,
          bookings: [BOOKING_ARTIST_1],
          filterArtistIds: [],
        }),
      { wrapper: makeWrapper() }
    )

    await waitFor(() => expect(result.current.isLoadingArtists).toBe(false))

    const alice = result.current.columns.find((c) => c.artistId === 'artist-1')
    const bob   = result.current.columns.find((c) => c.artistId === 'artist-2')

    expect(alice?.bookings).toHaveLength(1)
    expect(alice?.bookings[0].id).toBe('booking-1')
    expect(bob?.bookings).toHaveLength(0)
  })

  it('merges blocked slots into the correct artist column', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation((url) => {
      const u = String(url)
      if (u.includes('/api/artists')) {
        return Promise.resolve(new Response(JSON.stringify({ data: ARTISTS }), { status: 200 }))
      }
      // blocked-slots endpoint
      return Promise.resolve(new Response(JSON.stringify(BLOCKED_SLOTS), { status: 200 }))
    })

    const { result } = renderHook(
      () => useDayChairColumns({ date: TODAY, bookings: [], filterArtistIds: [] }),
      { wrapper: makeWrapper() }
    )

    await waitFor(() => expect(result.current.isLoadingBlocked).toBe(false))

    const alice = result.current.columns.find((c) => c.artistId === 'artist-1')
    const bob   = result.current.columns.find((c) => c.artistId === 'artist-2')

    expect(alice?.blockedSlots).toHaveLength(1)
    expect(alice?.blockedSlots[0].id).toBe('bs-1')
    expect(bob?.blockedSlots).toHaveLength(0)
  })

  it('surfaces error when artists fetch fails', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation(() =>
      Promise.resolve(new Response('', { status: 500 }))
    )

    const { result } = renderHook(
      () => useDayChairColumns({ date: TODAY, bookings: [], filterArtistIds: [] }),
      { wrapper: makeWrapper() }
    )

    await waitFor(() => result.current.error !== null)
    expect(result.current.error).toBeInstanceOf(Error)
    expect(result.current.columns).toEqual([])
  })
})

import { describe, it, expect, vi, afterEach } from 'vitest'
import { renderHook } from '@testing-library/react'
import { useNowLine } from '../use-now-line'

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Returns a Date for today at the given HH:mm (local time). */
function todayAt(hh: number, mm: number): Date {
  const d = new Date()
  d.setHours(hh, mm, 0, 0)
  return d
}

/** A date that is definitely not today (yesterday). */
function yesterday(): Date {
  const d = new Date()
  d.setDate(d.getDate() - 1)
  d.setHours(0, 0, 0, 0)
  return d
}

const SLOT_HEIGHT_PX = 128 // 30-min slot = 128px

afterEach(() => {
  vi.useRealTimers()
})

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('useNowLine', () => {
  it('returns topPx = -1 and isToday = false when date is not today', () => {
    const { result } = renderHook(() =>
      useNowLine({ date: yesterday(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )
    expect(result.current.isToday).toBe(false)
    expect(result.current.topPx).toBe(-1)
    expect(result.current.label).toBe('')
  })

  it('returns topPx = -1 when current time is before slotMinTime (7:30am with 08:00 start)', () => {
    vi.useFakeTimers()
    vi.setSystemTime(todayAt(7, 30))

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    expect(result.current.topPx).toBe(-1)
    // isToday is false when topPx is -1 per implementation
    expect(result.current.isToday).toBe(false)
  })

  it('returns correct topPx when today and current time is after slotMinTime', () => {
    vi.useFakeTimers()
    // Set time to 09:00 — 1 hour (60 min) after 08:00 slot start
    vi.setSystemTime(todayAt(9, 0))

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // offsetMinutes = 60; topPx = (60/30) * 128 = 256
    expect(result.current.isToday).toBe(true)
    expect(result.current.topPx).toBe(256)
  })

  it('returns correct topPx for a 30-min offset (08:30 → 1 slot = 128px)', () => {
    vi.useFakeTimers()
    vi.setSystemTime(todayAt(8, 30))

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // offsetMinutes = 30; topPx = (30/30) * 128 = 128
    expect(result.current.topPx).toBe(128)
    expect(result.current.isToday).toBe(true)
  })

  it('topPx = 0 exactly at slotMinTime (08:00)', () => {
    vi.useFakeTimers()
    vi.setSystemTime(todayAt(8, 0))

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    expect(result.current.topPx).toBe(0)
    expect(result.current.isToday).toBe(true)
  })

  it('label format is "NOW · H:MM AM/PM"', () => {
    vi.useFakeTimers()
    vi.setSystemTime(todayAt(14, 5)) // 2:05 PM

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // Should match "NOW · 2:05 PM" (en-US format)
    expect(result.current.label).toMatch(/^NOW · \d+:\d{2} [AP]M$/)
    expect(result.current.label).toContain('NOW ·')
  })

  it('label is empty when date is not today', () => {
    const { result } = renderHook(() =>
      useNowLine({ date: yesterday(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )
    expect(result.current.label).toBe('')
  })
})

/**
 * Integration tests for GET /api/bookings/calendar
 *
 * Strategy:
 * - Mock @/lib/supabase/server so no real DB is touched
 * - Mock @/lib/rate-limit to control 429 paths
 * - Mock @/lib/billing/feature-gate to control 403 paths
 * - Import and call the route handler directly
 */
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { NextRequest } from 'next/server'

// ---------------------------------------------------------------------------
// Shared mock state — mutated per test
// ---------------------------------------------------------------------------
let mockSession: { user: { id: string } } | null = { user: { id: 'user-1' } }
let mockProfile: { studio_id: string } | null = { studio_id: 'studio-1' }
let mockRateLimitSuccess = true
let mockFeatureGateThrows = false
let mockBookings: unknown[] = []

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

vi.mock('@/lib/supabase/server', () => ({
  createClient: vi.fn(async () => ({
    auth: {
      getSession: vi.fn(async () => ({
        data: { session: mockSession },
      })),
    },
    from: vi.fn((table: string) => {
      if (table === 'team_members') {
        return {
          select: () => ({
            eq: () => ({
              eq: () => ({
                single: async () => ({ data: mockProfile, error: mockProfile ? null : { message: 'not found' } }),
              }),
              single: async () => ({ data: mockProfile, error: mockProfile ? null : { message: 'not found' } }),
            }),
          }),
        }
      }
      if (table === 'bookings') {
        return {
          select: () => ({
            eq: () => ({
              eq: () => ({
                gte: () => ({
                  lt: () => ({
                    order: () => ({
                      limit: () =>
                        Promise.resolve({ data: mockBookings, error: null, count: mockBookings.length }),
                      in: () => ({
                        order: () => ({
                          limit: () =>
                            Promise.resolve({ data: mockBookings, error: null, count: mockBookings.length }),
                          in: () => ({
                            order: () => ({
                              limit: () =>
                                Promise.resolve({ data: mockBookings, error: null, count: mockBookings.length }),
                            }),
                          }),
                        }),
                      }),
                    }),
                  }),
                }),
              }),
            }),
          }),
        }
      }
      return {}
    }),
    rpc: vi.fn(async (name: string) => {
      if (name === 'check_feature_access') {
        if (mockFeatureGateThrows) return { data: false, error: null }
        return { data: true, error: null }
      }
      return { data: null, error: null }
    }),
  })),
}))

vi.mock('@/lib/rate-limit', () => ({
  authedRatelimit: {
    limit: vi.fn(async () => ({ success: mockRateLimitSuccess, limit: 60, remaining: 59, reset: Date.now() + 60000 })),
  },
}))

// ---------------------------------------------------------------------------
// Test helpers
// ---------------------------------------------------------------------------

function makeCalendarRequest(params: Record<string, string> = {}): NextRequest {
  const defaults = {
    from: '2026-04-23T08:00:00.000Z',
    to: '2026-04-23T22:00:00.000Z',
  }
  const merged = { ...defaults, ...params }
  const url = new URL('http://localhost/api/bookings/calendar')
  Object.entries(merged).forEach(([k, v]) => url.searchParams.set(k, v))
  return new NextRequest(url.toString(), {
    headers: { 'x-forwarded-for': '127.0.0.1' },
  })
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('GET /api/bookings/calendar', () => {
  beforeEach(() => {
    mockSession = { user: { id: 'user-1' } }
    mockProfile = { studio_id: 'studio-1' }
    mockRateLimitSuccess = true
    mockFeatureGateThrows = false
    mockBookings = []
    vi.clearAllMocks()
  })

  it('returns 401 when no session exists', async () => {
    mockSession = null
    const { GET } = await import('../calendar/route')
    const res = await GET(makeCalendarRequest())
    expect(res.status).toBe(401)
  })

  it('returns 429 when rate limit is exceeded', async () => {
    mockRateLimitSuccess = false
    const { GET } = await import('../calendar/route')
    const res = await GET(makeCalendarRequest())
    expect(res.status).toBe(429)
  })

  it('returns 403 when studio lacks calendar feature', async () => {
    mockFeatureGateThrows = true
    const { GET } = await import('../calendar/route')
    const res = await GET(makeCalendarRequest())
    expect(res.status).toBe(403)
  })

  it('returns 400 when from param is not a valid datetime', async () => {
    const { GET } = await import('../calendar/route')
    const res = await GET(makeCalendarRequest({ from: 'not-a-date' }))
    expect(res.status).toBe(400)
    const body = await res.json() as { error: string }
    expect(body.error).toBeDefined()
  })

  it('returns 400 when from param is missing', async () => {
    const url = new URL('http://localhost/api/bookings/calendar')
    url.searchParams.set('to', '2026-04-23T22:00:00.000Z')
    const { GET } = await import('../calendar/route')
    const res = await GET(new NextRequest(url.toString()))
    expect(res.status).toBe(400)
  })

  it('returns 200 with booking data for an authenticated user with calendar feature', async () => {
    mockBookings = [
      { id: 'booking-1', scheduled_at: '2026-04-23T10:00:00Z', status: 'confirmed' },
    ]
    const { GET } = await import('../calendar/route')
    const res = await GET(makeCalendarRequest())
    expect(res.status).toBe(200)
    const body = await res.json() as { data: unknown[] }
    expect(Array.isArray(body.data)).toBe(true)
  })
})

/**
 * Integration tests for PATCH /api/bookings/[id]
 *
 * Strategy:
 * - Mock @/lib/supabase/server (getAuthenticatedUser + createClient)
 * - Mock @/lib/queue (enqueueJob) to spy on SMS dispatch
 * - Mock @/lib/rate-limit
 * - Drive feature-gate (checkFeatureRpc) to control sms_reminders flag
 */
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { NextRequest } from 'next/server'

// ---------------------------------------------------------------------------
// Controllable state
// ---------------------------------------------------------------------------
let mockAuth: { user: { id: string; authId: string; email: string; full_name: string; avatar_url: null; is_platform_admin: boolean; created_at: string; updated_at: string }; studioId: string; role: 'owner' } | null = {
  user: { id: 'user-1', authId: 'user-1', email: 'a@b.com', full_name: 'Alice', avatar_url: null, is_platform_admin: false, created_at: '2026-01-01', updated_at: '2026-01-01' },
  studioId: 'studio-1',
  role: 'owner',
}

let mockRateLimitSuccess = true

// Original booking shape returned from DB
let mockOriginalBooking: {
  scheduled_at: string
  artist_id: string
  client_id: string
} | null = {
  scheduled_at: '2026-04-23T10:00:00Z',
  artist_id: 'artist-1',
  client_id: 'client-1',
}

// Updated booking shape returned after .update().select().single()
let mockUpdatedBooking: {
  id: string
  scheduled_at: string
  end_at: string
  duration_min: number
  status: string
  price_cents: number
  notes: null
  updated_at: string
} | null = {
  id: 'booking-1',
  scheduled_at: '2026-04-23T11:00:00Z', // changed — triggers SMS
  end_at: '2026-04-23T13:00:00Z',
  duration_min: 120,
  status: 'confirmed',
  price_cents: 0,
  notes: null,
  updated_at: '2026-04-23T10:00:00Z',
}

let mockUpdateError: { code?: string; message: string } | null = null
let mockSmsRemindersEnabled = true

// Client context for SMS — controls phone presence
let mockBookingCtx: {
  id: string
  client: { id: string; first_name: string; phone: string | null } | null
  artist: { display_name: string } | null
  service: { name: string } | null
  studio: { name: string } | null
} | null = {
  id: 'booking-1',
  client: { id: 'client-1', first_name: 'John', phone: '+15550001111' },
  artist: { display_name: 'Alice' },
  service: { name: 'Sleeve' },
  studio: { name: 'Inkville' },
}

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

const mockEnqueueJob = vi.fn().mockResolvedValue({ id: 'job-1' })

vi.mock('@/lib/queue', () => ({
  enqueueJob: (...args: unknown[]) => mockEnqueueJob(...args),
}))

vi.mock('@/lib/rate-limit', () => ({
