describe('PATCH /api/bookings/[id]', () => {
  beforeEach(() => {
    mockAuth = {
      user: { id: 'user-1', authId: 'user-1', email: 'a@b.com', full_name: 'Alice', avatar_url: null, is_platform_admin: false, created_at: '2026-01-01', updated_at: '2026-01-01' },
      studioId: 'studio-1',
      role: 'owner',
    }
    mockRateLimitSuccess = true
    mockOriginalBooking = {
      scheduled_at: '2026-04-23T10:00:00Z',
      artist_id: 'artist-1',
      client_id: 'client-1',
    }
    mockUpdatedBooking = {
      id: 'booking-1',
      scheduled_at: '2026-04-23T11:00:00Z',
      end_at: '2026-04-23T13:00:00Z',
      duration_min: 120,
      status: 'confirmed',
      price_cents: 0,
      notes: null,
      updated_at: '2026-04-23T10:00:00Z',
    }
    mockUpdateError = null
    mockSmsRemindersEnabled = true
    mockBookingCtx = {
      id: 'booking-1',
      client: { id: 'client-1', first_name: 'John', phone: '+15550001111' },
      artist: { display_name: 'Alice' },
      service: { name: 'Sleeve' },
      studio: { name: 'Inkville' },
    }
    mockEnqueueJob.mockClear()
  })

  it('returns 401 when unauthenticated', async () => {
    mockAuth = null
    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(makeRequest(VALID_BOOKING_ID, { notes: 'hello' }), {
      params: Promise.resolve({ id: VALID_BOOKING_ID }),
    })
    expect(res.status).toBe(401)
  })

  it('returns 429 when rate limited', async () => {
    mockRateLimitSuccess = false
    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(makeRequest(VALID_BOOKING_ID, { notes: 'hello' }), {
      params: Promise.resolve({ id: VALID_BOOKING_ID }),
    })
    expect(res.status).toBe(429)
  })

  it('returns 400 for invalid booking UUID', async () => {
    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(makeRequest('not-a-uuid', { notes: 'hello' }), {
      params: Promise.resolve({ id: 'not-a-uuid' }),
    })
    expect(res.status).toBe(400)
  })

  it('returns 200 and does NOT call enqueueJob when suppress_notifications=true', async () => {
    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(
      makeRequest(VALID_BOOKING_ID, {
        scheduled_at: '2026-04-23T12:00:00.000Z', // change triggers SMS normally
        suppress_notifications: true,
      }),
      { params: Promise.resolve({ id: VALID_BOOKING_ID }) }
    )
    expect(res.status).toBe(200)
    // Allow async fire-and-forget to settle
    await new Promise((r) => setTimeout(r, 50))
    expect(mockEnqueueJob).not.toHaveBeenCalled()
  })

  it('calls enqueueJob with send-sms when scheduled_at changes and sms_reminders is on and client has phone', async () => {
    // updated booking has different scheduled_at from original
    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(
      makeRequest(VALID_BOOKING_ID, {
        scheduled_at: '2026-04-23T11:00:00.000Z',
      }),
      { params: Promise.resolve({ id: VALID_BOOKING_ID }) }
    )
    expect(res.status).toBe(200)
    // Fire-and-forget: wait for microtask queue
    await new Promise((r) => setTimeout(r, 50))
    expect(mockEnqueueJob).toHaveBeenCalledWith(
      'send-sms',
      expect.objectContaining({ studioId: 'studio-1' })
    )
  })

  it('calls enqueueJob when artist_id changes (even if scheduled_at is same)', async () => {
    // Same scheduled_at in both original + updated so only artist change triggers
    if (mockUpdatedBooking) {
      mockUpdatedBooking.scheduled_at = '2026-04-23T10:00:00Z' // same as original
    }

    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(
      makeRequest(VALID_BOOKING_ID, {
        artist_id: '00000000-0000-0000-0000-000000000099', // different from 'artist-1'
      }),
      { params: Promise.resolve({ id: VALID_BOOKING_ID }) }
    )
    expect(res.status).toBe(200)
    await new Promise((r) => setTimeout(r, 50))
    expect(mockEnqueueJob).toHaveBeenCalledWith('send-sms', expect.any(Object))
  })

  it('does NOT call enqueueJob when sms_reminders feature is off', async () => {
    mockSmsRemindersEnabled = false
    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(
      makeRequest(VALID_BOOKING_ID, {
        scheduled_at: '2026-04-23T11:00:00.000Z',
      }),
      { params: Promise.resolve({ id: VALID_BOOKING_ID }) }
    )
    expect(res.status).toBe(200)
    await new Promise((r) => setTimeout(r, 50))
    expect(mockEnqueueJob).not.toHaveBeenCalled()
  })

  it('does NOT call enqueueJob when client has no phone', async () => {
    if (mockBookingCtx?.client) {
      mockBookingCtx.client.phone = null
    }
    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(
      makeRequest(VALID_BOOKING_ID, {
        scheduled_at: '2026-04-23T11:00:00.000Z',
      }),
      { params: Promise.resolve({ id: VALID_BOOKING_ID }) }
    )
    expect(res.status).toBe(200)
    await new Promise((r) => setTimeout(r, 50))
    expect(mockEnqueueJob).not.toHaveBeenCalled()
  })

  it('returns 200 even when SMS dispatch would fail (non-blocking)', async () => {
    // Make enqueueJob throw — the PATCH should still return 200
    mockEnqueueJob.mockRejectedValueOnce(new Error('Redis unavailable'))

    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(
      makeRequest(VALID_BOOKING_ID, {
        scheduled_at: '2026-04-23T11:00:00.000Z',
      }),
      { params: Promise.resolve({ id: VALID_BOOKING_ID }) }
    )

    // Must resolve to 200 before the async SMS dispatch settles
    expect(res.status).toBe(200)
    // Let fire-and-forget settle — should not throw to caller
    await new Promise((r) => setTimeout(r, 100))
  })

  it('returns 409 on booking conflict (DB error code 23P01)', async () => {
    mockUpdateError = { code: '23P01', message: 'exclusion constraint' }
    const { PATCH } = await import('../[id]/route')
    const res = await PATCH(
      makeRequest(VALID_BOOKING_ID, { scheduled_at: '2026-04-23T11:00:00.000Z' }),
      { params: Promise.resolve({ id: VALID_BOOKING_ID }) }
    )
    expect(res.status).toBe(409)
  })
})

/**
 * Component tests for CopyBookingLinkButton
 *
 * Mocks:
 * - fetch: controls the /api/booking-links response
 * - navigator.clipboard.writeText: spy to assert copy calls
 * - sonner toast: spy to assert toast calls
 * - @tanstack/react-query: wraps with real QueryClient
 */
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import React from 'react'
import { CopyBookingLinkButton } from '../CopyBookingLinkButton'

// ---------------------------------------------------------------------------
// Mock sonner
// ---------------------------------------------------------------------------
const mockToastSuccess = vi.fn()
const mockToastError = vi.fn()

vi.mock('sonner', () => ({
  toast: {
    success: (...args: unknown[]) => mockToastSuccess(...args),
    error: (...args: unknown[]) => mockToastError(...args),
  },
}))

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeWrapper() {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: 0 } },
  })
  return ({ children }: { children: React.ReactNode }) =>
    React.createElement(QueryClientProvider, { client }, children)
}

const STUDIO_URL = 'https://book.inkos.app/test-studio'

function renderButton() {
  return render(React.createElement(CopyBookingLinkButton), { wrapper: makeWrapper() })
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('CopyBookingLinkButton', () => {
  beforeEach(() => {
    vi.restoreAllMocks()
    mockToastSuccess.mockClear()
    mockToastError.mockClear()
  })

  it('button is disabled while loading (fetch not resolved)', async () => {
    vi.spyOn(globalThis, 'fetch').mockImplementation(() => new Promise(() => {/* never */}))
    renderButton()
    const button = screen.getByRole('button', { name: /copy booking link/i })
    expect(button).toBeDisabled()
  })

  it('button is disabled when API returns no studioUrl', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      new Response(JSON.stringify({ data: { studioUrl: '', studioSlug: 'test' } }), { status: 200 })
    )
    renderButton()
    await waitFor(() => {
      const button = screen.getByRole('button', { name: /copy booking link/i })
      expect(button).toBeDisabled()
    })
  })

  it('button is enabled and clicking copies studioUrl to clipboard', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      new Response(
        JSON.stringify({ data: { studioUrl: STUDIO_URL, studioSlug: 'test-studio' } }),
        { status: 200 }
      )
    )

    const clipboardSpy = vi.fn().mockResolvedValue(undefined)
    Object.defineProperty(navigator, 'clipboard', {
      value: { writeText: clipboardSpy },
      writable: true,
      configurable: true,
    })

    renderButton()

    const button = screen.getByRole('button', { name: /copy booking link/i })
    await waitFor(() => expect(button).not.toBeDisabled())

    await userEvent.click(button)

    expect(clipboardSpy).toHaveBeenCalledWith(STUDIO_URL)
    await waitFor(() =>
      expect(mockToastSuccess).toHaveBeenCalledWith(
        'Booking link copied',
        expect.objectContaining({ description: STUDIO_URL })
      )
    )
  })

  it('shows error toast when clipboard write fails', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      new Response(
        JSON.stringify({ data: { studioUrl: STUDIO_URL, studioSlug: 'test' } }),
        { status: 200 }
      )
    )

    Object.defineProperty(navigator, 'clipboard', {
      value: { writeText: vi.fn().mockRejectedValue(new Error('NotAllowedError')) },
      writable: true,
      configurable: true,
    })

    renderButton()
    const button = screen.getByRole('button', { name: /copy booking link/i })
    await waitFor(() => expect(button).not.toBeDisabled())

    await userEvent.click(button)

    await waitFor(() =>
      expect(mockToastError).toHaveBeenCalledWith('Failed to copy booking link')
    )
  })

  it('shows error toast when data not yet available on click', async () => {
    // fetch resolves but with null studioUrl — disabled button, so clicking does nothing
    // test the "guard" path by directly calling the component before data loads
    vi.spyOn(globalThis, 'fetch').mockImplementation(() => new Promise(() => {/* never */}))
    renderButton()
    const button = screen.getByRole('button', { name: /copy booking link/i })
    // Button disabled — clicking should not invoke clipboard
    Object.defineProperty(navigator, 'clipboard', {
      value: { writeText: vi.fn() },
      writable: true,
      configurable: true,
    })
    // disabled button won't fire onClick, so no clipboard call expected
    expect(button).toBeDisabled()
  })
})

