/**
 * Integration tests for GET /api/bookings/calendar
 */
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { NextRequest } from 'next/server'
import { FeatureGateError } from '@/lib/billing/feature-gate'

// ---------------------------------------------------------------------------
// Mutable state controlled per test
// ---------------------------------------------------------------------------
let mockAuth: { user: { id: string }; studioId: string; role: string } | null = {
  user: { id: 'user-1' },
  studioId: 'studio-1',
  role: 'owner',
}
let mockRateLimitSuccess = true
let mockFeatureGateThrows = false
let mockBookings: unknown[] = []
let mockDbError: { message: string } | null = null

// ---------------------------------------------------------------------------
// Mocks — declared before any import of the route
// ---------------------------------------------------------------------------

vi.mock('@/lib/supabase/server', () => ({
  getAuthenticatedUser: vi.fn(async () => mockAuth),
  createClient: vi.fn(async () => {
    // Build a flexible query-chain mock using a proxy
    function makeChainable(finalResult: () => Promise<unknown>): unknown {
      const handler: ProxyHandler<object> = {
        get(_target, prop) {
          if (prop === 'then' || prop === 'catch' || prop === 'finally') {
            return undefined // Not a promise itself
          }
          // Terminal methods
          if (prop === 'limit') {
            return () => finalResult()
          }
          // Chainable methods — return same proxy
          return () => new Proxy({}, handler)
        },
      }
      return new Proxy({}, handler)
    }

    return {
      from: vi.fn(() => ({
        select: vi.fn(() =>
          makeChainable(() =>
            Promise.resolve({
              data: mockDbError ? null : mockBookings,
              error: mockDbError,
              count: mockBookings.length,
            })
          )
        ),
      })),
      rpc: vi.fn(async () => ({ data: true, error: null })),
    }
  }),
}))

vi.mock('@/lib/rate-limit', () => ({
  authedRatelimit: {
    limit: vi.fn(async () => ({
      success: mockRateLimitSuccess,
      limit: 60,
      remaining: 59,
      reset: Date.now() + 60000,
    })),
  },
}))

vi.mock('@/lib/billing/feature-gate', async (importOriginal) => {
  const original = await importOriginal<typeof import('@/lib/billing/feature-gate')>()
  return {
    ...original,
    requireFeatureRpc: vi.fn(async () => {
      if (mockFeatureGateThrows) throw new FeatureGateError('calendar')
    }),
  }
})

// ---------------------------------------------------------------------------
// Route import (after mocks)
// ---------------------------------------------------------------------------
const { GET } = await import('@/app/api/bookings/calendar/route')

// ---------------------------------------------------------------------------
// Helper
// ---------------------------------------------------------------------------
function makeCalendarRequest(params: Record<string, string> = {}): NextRequest {
  const defaults = {
    from: '2026-04-23T08:00:00.000Z',
    to: '2026-04-23T22:00:00.000Z',
  }
  const merged = { ...defaults, ...params }
  const url = new URL('http://localhost/api/bookings/calendar')
  Object.entries(merged).forEach(([k, v]) => url.searchParams.set(k, v))
  return new NextRequest(url.toString(), {
    headers: { 'x-forwarded-for': '127.0.0.1' },
  })
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------
describe('GET /api/bookings/calendar', () => {
  beforeEach(() => {
