  })

  it('calls enqueueJob when artist_id changes but scheduled_at is the same', async () => {
    // Make updated scheduled_at match original → only artist change triggers SMS
    if (mockUpdatedBooking) {
      mockUpdatedBooking.scheduled_at = '2026-04-23T10:00:00Z' // same as original
    }
    const res = await PATCH(
      makeRequest(VALID_ID, {
        artist_id: '00000000-0000-0000-0000-000000000099',
      }),
      { params: Promise.resolve({ id: VALID_ID }) }
    )
    expect(res.status).toBe(200)
    await new Promise((r) => setTimeout(r, 50))
    expect(mockEnqueueJob).toHaveBeenCalled()
  })

  it('does NOT call enqueueJob when sms_reminders feature is off', async () => {
    mockSmsRemindersEnabled = false
    const res = await PATCH(
      makeRequest(VALID_ID, { scheduled_at: '2026-04-23T11:00:00.000Z' }),
      { params: Promise.resolve({ id: VALID_ID }) }
    )
    expect(res.status).toBe(200)
    await new Promise((r) => setTimeout(r, 50))
    expect(mockEnqueueJob).not.toHaveBeenCalled()
  })

  it('does NOT call enqueueJob when client has no phone', async () => {
    if (mockBookingCtx?.client) mockBookingCtx.client.phone = null
    const res = await PATCH(
      makeRequest(VALID_ID, { scheduled_at: '2026-04-23T11:00:00.000Z' }),
      { params: Promise.resolve({ id: VALID_ID }) }
    )
    expect(res.status).toBe(200)
    await new Promise((r) => setTimeout(r, 50))
    expect(mockEnqueueJob).not.toHaveBeenCalled()
  })

  it('returns 200 even when SMS dispatch fails (non-blocking)', async () => {
    mockEnqueueJob.mockRejectedValueOnce(new Error('Redis unavailable'))
