import { describe, it, expect, vi, afterEach } from 'vitest'
import { renderHook } from '@testing-library/react'
import { useNowLine } from '../use-now-line'

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Returns a Date for today at the given HH:mm (local time). */
function todayAt(hh: number, mm: number): Date {
  const d = new Date()
  d.setHours(hh, mm, 0, 0)
  return d
}

/** A date that is definitely not today (yesterday). */
function yesterday(): Date {
  const d = new Date()
  d.setDate(d.getDate() - 1)
  d.setHours(0, 0, 0, 0)
  return d
}

const SLOT_HEIGHT_PX = 128 // 30-min slot = 128px

afterEach(() => {
  vi.useRealTimers()
})

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('useNowLine', () => {
  it('returns topPx = -1 and isToday = false when date is not today', () => {
    const { result } = renderHook(() =>
      useNowLine({ date: yesterday(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )
    expect(result.current.isToday).toBe(false)
    expect(result.current.topPx).toBe(-1)
    expect(result.current.label).toBe('')
  })

  it('returns topPx = -1 and isToday = true when current time is before slotMinTime (7:30am with 08:00 start)', () => {
    vi.useFakeTimers()
    vi.setSystemTime(todayAt(7, 30))

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    expect(result.current.topPx).toBe(-1)
    // Implementation returns isToday: true even before slotMin — consumer gates on topPx >= 0
    expect(result.current.isToday).toBe(true)
  })

  it('returns correct topPx when today and current time is after slotMinTime', () => {
    vi.useFakeTimers()
    // Set time to 09:00 — 1 hour (60 min) after 08:00 slot start
    vi.setSystemTime(todayAt(9, 0))

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // offsetMinutes = 60; topPx = (60/30) * 128 = 256
    expect(result.current.isToday).toBe(true)
    expect(result.current.topPx).toBe(256)
  })

  it('returns correct topPx for a 30-min offset (08:30 → 1 slot = 128px)', () => {
    vi.useFakeTimers()
    vi.setSystemTime(todayAt(8, 30))

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // offsetMinutes = 30; topPx = (30/30) * 128 = 128
    expect(result.current.topPx).toBe(128)
    expect(result.current.isToday).toBe(true)
  })

  it('topPx = 0 exactly at slotMinTime (08:00)', () => {
    vi.useFakeTimers()
    vi.setSystemTime(todayAt(8, 0))

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    expect(result.current.topPx).toBe(0)
    expect(result.current.isToday).toBe(true)
  })

  it('label format is "NOW · H:MM AM/PM"', () => {
    vi.useFakeTimers()
    vi.setSystemTime(todayAt(14, 5)) // 2:05 PM

    const { result } = renderHook(() =>
      useNowLine({ date: new Date(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // Should match "NOW · 2:05 PM" (en-US format)
    expect(result.current.label).toMatch(/^NOW · \d+:\d{2} [AP]M$/)
    expect(result.current.label).toContain('NOW ·')
  })

  it('label is empty when date is not today', () => {
    const { result } = renderHook(() =>
      useNowLine({ date: yesterday(), slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )
    expect(result.current.label).toBe('')
  })
})

/**
 * Tests for useNowLine hook.
 *
 * The hook wraps a pure `computeNowLine` function with state + setInterval.
 * We test the initial synchronous state by:
 * 1. Setting fake system time before render
 * 2. Reading result.current immediately after renderHook (no await needed)
 * 3. Unmounting immediately to prevent setInterval memory leaks
 *
 * Note: vi.useFakeTimers() replaces setInterval — the hook's 60s tick never fires
 * unless we explicitly call vi.advanceTimersByTime(). This keeps tests fast + isolated.
 */
import { describe, it, expect, vi, afterEach } from 'vitest'
import { renderHook } from '@testing-library/react'
import { useNowLine } from '../use-now-line'

const SLOT_HEIGHT_PX = 128 // 30-min slot = 128px

afterEach(() => {
  vi.useRealTimers()
})

// ---------------------------------------------------------------------------
// Helper — set today's time then return a today Date at midnight for `date` param
// ---------------------------------------------------------------------------
function setupTodayAt(hh: number, mm: number): Date {
  vi.useFakeTimers()
  const now = new Date()
  now.setHours(hh, mm, 0, 0)
  vi.setSystemTime(now)
  // Return today at midnight — what `date` param would be for "today's calendar view"
  const today = new Date(now)
  today.setHours(0, 0, 0, 0)
  return today
}

function setupYesterday(): Date {
  vi.useFakeTimers()
  const d = new Date()
  d.setDate(d.getDate() - 1)
  d.setHours(12, 0, 0, 0)
  vi.setSystemTime(d)
  const yesterday = new Date(d)
  yesterday.setHours(0, 0, 0, 0)
  return yesterday
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('useNowLine', () => {
  it('isToday = false and topPx = -1 when date is yesterday', () => {
    const yesterday = setupYesterday()

    const { result, unmount } = renderHook(() =>
      useNowLine({ date: yesterday, slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    expect(result.current.isToday).toBe(false)
    expect(result.current.topPx).toBe(-1)
    expect(result.current.label).toBe('')
    unmount()
  })

  it('topPx = -1 and isToday = true when current time is before slotMinTime (07:30 with 08:00 start)', () => {
    const today = setupTodayAt(7, 30)

    const { result, unmount } = renderHook(() =>
      useNowLine({ date: today, slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    expect(result.current.topPx).toBe(-1)
    // Implementation sets isToday: true even before slot start — consumer gates on topPx >= 0
    expect(result.current.isToday).toBe(true)
    unmount()
  })

  it('returns topPx = 256 when time is 09:00 with 08:00 slot start (1h = 2 slots × 128px)', () => {
    const today = setupTodayAt(9, 0)

    const { result, unmount } = renderHook(() =>
      useNowLine({ date: today, slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // offsetMinutes = 60; topPx = (60/30) * 128 = 256
    expect(result.current.isToday).toBe(true)
    expect(result.current.topPx).toBe(256)
    unmount()
  })

  it('returns topPx = 128 for a 30-min offset (08:30 → 1 slot)', () => {
    const today = setupTodayAt(8, 30)

    const { result, unmount } = renderHook(() =>
      useNowLine({ date: today, slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // offsetMinutes = 30; topPx = (30/30) * 128 = 128
    expect(result.current.topPx).toBe(128)
    expect(result.current.isToday).toBe(true)
    unmount()
  })

  it('topPx = 0 exactly at slotMinTime (08:00)', () => {
    const today = setupTodayAt(8, 0)

    const { result, unmount } = renderHook(() =>
      useNowLine({ date: today, slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    expect(result.current.topPx).toBe(0)
    expect(result.current.isToday).toBe(true)
    unmount()
  })

  it('label format is "NOW · H:MM AM/PM" when visible', () => {
    const today = setupTodayAt(14, 5) // 2:05 PM

    const { result, unmount } = renderHook(() =>
      useNowLine({ date: today, slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    // Should match "NOW · 2:05 PM" (en-US format)
    expect(result.current.label).toMatch(/^NOW · \d+:\d{2} [AP]M$/)
    expect(result.current.label).toContain('NOW ·')
    unmount()
  })

  it('label is empty when date is not today', () => {
    const yesterday = setupYesterday()

    const { result, unmount } = renderHook(() =>
      useNowLine({ date: yesterday, slotMinTime: '08:00', slotHeightPx: SLOT_HEIGHT_PX })
    )

    expect(result.current.label).toBe('')
    unmount()
  })
})

