/** Returns yesterday's midnight Date. Does NOT change fake timers — system time stays "today". */
function yesterdayDate(): Date {
  const d = new Date()
  d.setDate(d.getDate() - 1)
  d.setHours(0, 0, 0, 0)
  return d
}
